export interface SkillItem {
  id: string;
  name: string;
  cardBg: string;
  borderColor: string;
  hoverBorder: string;
  hoverShadow: string;
  svg: (isCompact: boolean) => React.ReactNode;
}

// Responsive icon dimensions: compact on mobile, expansive on desktop
const getIconClass = (isCompact: boolean, customClasses: string = "") => {
  if (isCompact) {
    return `h-6 w-6 sm:h-7 sm:w-7 ${customClasses} object-contain transition-transform duration-300`;
  }
  return `h-10 w-10 lg:h-12 lg:w-12 ${customClasses} object-contain transition-transform duration-300`;
};

