export interface Skiper30Props {
  className?: string;
}

const Skiper30 = ({ className = "" }: Skiper30Props) => {
  const sectionRef = useRef<HTMLElement>(null);
  const [dimension, setDimension] = useState({ width: 0, height: 0 });

  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ["start end", "end start"],
  });

  const { height } = dimension;
  // Parallax transform channels with distinct travel speeds
  const y1 = useTransform(scrollYProgress, [0, 1], [0, height * 0.35]);
  const y2 = useTransform(scrollYProgress, [0, 1], [0, height * 0.75]);
  const y3 = useTransform(scrollYProgress, [0, 1], [0, height * 0.25]);
  const y4 = useTransform(scrollYProgress, [0, 1], [0, height * 0.65]);
  const y5 = useTransform(scrollYProgress, [0, 1], [0, height * 0.45]);

  useEffect(() => {
    const lenis = new Lenis({
      lerp: 0.1,
      smoothWheel: true,
      wheelMultiplier: 0.95,
      touchMultiplier: 1.0,
    });

    let animationFrameId: number;

    const raf = (time: number) => {
      lenis.raf(time);
      animationFrameId = requestAnimationFrame(raf);
    };

    const resize = () => {
      setDimension({ width: window.innerWidth, height: window.innerHeight });
    };

    window.addEventListener("resize", resize);
    animationFrameId = requestAnimationFrame(raf);
    resize();

    return () => {
      window.removeEventListener("resize", resize);
      cancelAnimationFrame(animationFrameId);
      lenis.destroy();
    };
  }, []);

  return (
    <section
      ref={sectionRef}
      id="skills"
      className={`relative w-full bg-[var(--section-alt-bg)] text-[var(--foreground)] scroll-mt-16 ${className}`}
    >
      {/* Anchor for projects compatibility */}
      <span id="projects" className="absolute -top-24 pointer-events-none" />

      {/* Section Header */}
      <div className="relative flex flex-col items-center justify-center text-center px-4 pt-16 sm:pt-24 lg:pt-28 pb-8 sm:pb-12">
        <div className="flex flex-col items-center gap-3.5 max-w-2xl">
          <div className="inline-flex items-center gap-2 rounded-full border border-[var(--border)] bg-[var(--card-bg)] px-3.5 py-1.5 text-xs font-medium text-[var(--muted-fg)] shadow-xs">
            <span className="h-2 w-2 rounded-full bg-amber-500 animate-pulse" />
            <span>Technical Stack &amp; Tools</span>
          </div>

          <h2 className="text-2xl sm:text-4xl lg:text-5xl font-extrabold tracking-tight text-[var(--foreground)]">
            Skills &amp; Technologies
          </h2>

          <p className="text-xs sm:text-sm lg:text-base text-[var(--muted-fg)] max-w-lg px-2">
            A visual showcase of the programming languages, enterprise frameworks, databases, and developer tools powering my full-stack applications.
          </p>

          <span className="relative max-w-[14ch] text-[11px] sm:text-xs uppercase tracking-widest text-[var(--muted-fg)] pt-4 after:absolute after:left-1/2 after:top-full after:h-10 after:w-px after:bg-gradient-to-b after:from-neutral-300 after:to-neutral-900 dark:after:from-neutral-600 dark:after:to-neutral-100 after:content-['']">
            scroll to explore
          </span>
        </div>
      </div>

      {/* =========================================================================
          MOBILE & TABLET: Exactly 3 Columns with Compact Cells (< 1024px)
          Decreased cell size, tightly proportioned, zero edge-overflow
          ========================================================================= */}
      <div className="relative box-border flex lg:hidden h-[95vh] sm:h-[110vh] gap-2 sm:gap-3 overflow-hidden bg-[var(--background)] px-2.5 sm:px-4 py-2 justify-center items-start">
        <SkillColumn
          skills={MOBILE_COLS[0]}
          y={y1}
          topOffset="-top-[12%]"
          className="flex-1 max-w-[105px] sm:max-w-[125px]"
          isCompact={true}
        />
        <SkillColumn
          skills={MOBILE_COLS[1]}
          y={y2}
          topOffset="-top-[32%]"
          className="flex-1 max-w-[105px] sm:max-w-[125px]"
          isCompact={true}
        />
        <SkillColumn
          skills={MOBILE_COLS[2]}
          y={y3}
          topOffset="-top-[18%]"
          className="flex-1 max-w-[105px] sm:max-w-[125px]"
          isCompact={true}
        />
      </div>

      {/* =========================================================================
          DESKTOP: Exactly 5 Columns (>= 1024px)
          ========================================================================= */}
      <div className="relative box-border hidden lg:flex h-[144vh] gap-3.5 lg:gap-4 overflow-hidden bg-[var(--background)] px-4 lg:px-6 py-2 justify-center">
        <SkillColumn
          skills={DESKTOP_COLS[0]}
          y={y1}
          topOffset="-top-[12%]"
          className="w-1/5 max-w-[210px]"
          isCompact={false}
        />
        <SkillColumn
          skills={DESKTOP_COLS[1]}
          y={y2}
          topOffset="-top-[38%]"
          className="w-1/5 max-w-[210px]"
          isCompact={false}
        />
        <SkillColumn
          skills={DESKTOP_COLS[2]}
          y={y3}
          topOffset="-top-[10%]"
          className="w-1/5 max-w-[210px]"
          isCompact={false}
        />
        <SkillColumn
          skills={DESKTOP_COLS[3]}
          y={y4}
          topOffset="-top-[32%]"
          className="w-1/5 max-w-[210px]"
          isCompact={false}
        />
        <SkillColumn
          skills={DESKTOP_COLS[4]}
          y={y5}
          topOffset="-top-[20%]"
          className="w-1/5 max-w-[210px]"
          isCompact={false}
        />
      </div>

      {/* Outro spacer */}
      <div className="relative flex items-center justify-center text-center py-16 sm:py-20 bg-[var(--section-alt-bg)]">
        <span className="relative max-w-[14ch] text-xs uppercase tracking-widest text-[var(--muted-fg)] after:absolute after:left-1/2 after:top-full after:h-10 after:w-px after:bg-gradient-to-b after:from-neutral-300 after:to-neutral-900 dark:after:from-neutral-600 dark:after:to-neutral-100 after:content-['']">
          scroll to explore
        </span>
      </div>
    </section>
  );
};

interface SkillColumnProps {
  skills: SkillItem[];
  y: MotionValue<number>;
  topOffset: string;
  className?: string;
  isCompact: boolean;
}

const SkillColumn = ({ skills, y, topOffset, className = "", isCompact }: SkillColumnProps) => {
  return (
    <motion.div
      className={`relative flex min-w-0 shrink-0 flex-col ${
        isCompact ? "gap-2 sm:gap-2.5" : "gap-3.5 lg:gap-4"
      } will-change-transform transform-gpu ${topOffset} ${className}`}
      style={{ y }}
    >
      {skills.map((skill) => (
        <div
          key={skill.id}
          title={skill.name}
          className={`group relative flex ${
            isCompact
              ? "aspect-square rounded-xl p-2 sm:p-2.5"
              : "aspect-[1.25/1] rounded-2xl lg:rounded-3xl p-3.5 lg:p-4.5"
          } w-full shrink-0 items-center justify-center border ${skill.borderColor} ${skill.cardBg} ${
            skill.hoverBorder
          } ${skill.hoverShadow} shadow-[0_2px_10px_rgba(0,0,0,0.03)] dark:shadow-[0_4px_20px_rgba(0,0,0,0.35)] backdrop-blur-xs transition-all duration-300 hover:scale-[1.04] hover:-translate-y-0.5 hover:shadow-md select-none overflow-hidden cursor-pointer`}
        >
          {/* Subtle hover background highlight */}
          <div className="pointer-events-none absolute inset-0 opacity-0 transition-opacity duration-300 group-hover:opacity-100 bg-gradient-to-tr from-white/20 via-transparent to-white/40 dark:from-white/5 dark:to-transparent" />

          {/* Pure SVG Brand Logo (No text label inside as requested) */}
          <div className="relative z-10 flex items-center justify-center w-full h-full transition-transform duration-300 group-hover:scale-110">
            {skill.svg(isCompact)}
          </div>
        </div>
      ))}
    </motion.div>
  );
};

export { Skiper30, Skiper30 as SkillsParallax };
export default Skiper30;
